// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Fingerprintimport androidx.compose.material.icons.filled.Lockimport androidx.compose.material3.Iconimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.CircleIconButtonimport com.roshan.persona.ui.components.NeoButton/** * App Lock screen — biometric / PIN gate. * * Wired to: *   - AppLockManager (passed as parameters — lock state, attempts remaining) *   - AuthenticationManager (callbacks for biometric/PIN verification) * * @param userName displayed in greeting * @param biometricAvailable whether biometric can be used * @param onBiometricUnlock callback to trigger BiometricPrompt * @param onPinSubmit callback when PIN entered (4 digits) * @param onUsePasskey callback to switch to passkey auth * @param attemptsRemaining attempts before lockout (e.g. 3, 2, 1) * @param lockoutMs remaining lockout time if locked out (0 = not locked) */@Composablefun AppLockScreen(    userName: String,    biometricAvailable: Boolean,    onBiometricUnlock: () -> Unit,    onPinSubmit: (String) -> Unit,    onUsePasskey: () -> Unit,    attemptsRemaining: Int,    lockoutMs: Long,    modifier: Modifier = Modifier,) {    var pin by remember { mutableStateOf("") }    val isLockedOut = lockoutMs > 0    Column(        modifier = modifier            .fillMaxSize()            .background(MaterialTheme.colorScheme.background)            .padding(32.dp),        horizontalAlignment = Alignment.CenterHorizontally,        verticalArrangement = Arrangement.Center,    ) {        // Lock icon        Box(            modifier = Modifier                .size(80.dp)                .background(                    color = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f),                    shape = CircleShape,                ),            contentAlignment = Alignment.Center,        ) {            Icon(                imageVector = Icons.Default.Lock,                contentDescription = null,                tint = MaterialTheme.colorScheme.primary,                modifier = Modifier.size(40.dp),            )        }        Spacer(modifier = Modifier.size(24.dp))        Text(            text = "Welcome back, $userName",            style = MaterialTheme.typography.headlineLarge,            fontWeight = FontWeight.Bold,            color = MaterialTheme.colorScheme.onBackground,        )        Spacer(modifier = Modifier.size(8.dp))        if (isLockedOut) {            Text(                text = "Locked out. Try again in ${lockoutMs / 1000}s.",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.error,            )        } else if (attemptsRemaining < 3) {            Text(                text = "$attemptsRemaining attempts remaining",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.error,            )        } else {            Text(                text = "Unlock to continue",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )        }        Spacer(modifier = Modifier.size(32.dp))        // Biometric button (preferred)        if (biometricAvailable && !isLockedOut) {            NeoButton(                text = "Unlock with Biometric",                onClick = onBiometricUnlock,                icon = Icons.Default.Fingerprint,                modifier = Modifier.fillMaxWidth(),            )            Spacer(modifier = Modifier.size(16.dp))            Text(                text = "— or enter PIN —",                style = MaterialTheme.typography.labelMedium,                color = MaterialTheme.colorScheme.onSurfaceVariant,            )            Spacer(modifier = Modifier.size(16.dp))        }        // PIN display (dots)        Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {            repeat(4) { i ->                val filled = i < pin.length                Box(                    modifier = Modifier                        .size(16.dp)                        .background(                            color = if (filled) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,                            shape = CircleShape,                        ),                )            }        }        Spacer(modifier = Modifier.size(16.dp))        // Number pad        val keys = listOf("1", "2", "3", "4", "5", "6", "7", "8", "9", "←", "0", "✓")        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {            keys.chunked(3).forEach { row ->                Row(                    modifier = Modifier.fillMaxWidth(),                    horizontalArrangement = Arrangement.SpaceEvenly,                ) {                    row.forEach { key ->                        Box(                            modifier = Modifier                                .size(56.dp)                                .background(                                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),                                    shape = CircleShape,                                )                                .clickable(enabled = !isLockedOut) {                                    when (key) {                                        "←" -> pin = pin.dropLast(1)                                        "✓" -> {                                            if (pin.length == 4) {                                                onPinSubmit(pin)                                                pin = ""                                            }                                        }                                        else -> if (pin.length < 4) pin += key                                    }                                },                            contentAlignment = Alignment.Center,                        ) {                            Text(                                text = key,                                style = MaterialTheme.typography.titleLarge,                                color = MaterialTheme.colorScheme.onSurface,                            )                        }                    }                }            }        }        Spacer(modifier = Modifier.size(24.dp))        // Passkey alternative        Text(            text = "Use passkey instead",            style = MaterialTheme.typography.labelMedium,            color = MaterialTheme.colorScheme.primary,            modifier = Modifier.clickable(onClick = onUsePasskey),        )    }}